#!/usr/bin/env bash



# set -e: exit on errors
# set -x: verbose logging

set -ex



# Configure bash globbing for recursive cp command

shopt -s globstar



# Set variables

PORT="_build/BK Reloaded (Lighthouse)"

echo -n "Type dds if you converted the textures to that format, otherwise just press enter to use PNG (default): "
read VALUE

case "$VALUE" in

  dds)
    EXT=".dds"
    ;;

  *)
    EXT=".png"
    ;;
esac



# Remove and recreate work directories

rm -drf "$PORT"
rm -drf "_temp"

mkdir -p "$PORT"
mkdir -p "_temp"



# Copy textures to work directories

cp -r "Ports/Lighthouse/"* "$PORT"
cp **"/Banjo-Kazooie"*"$EXT" "_temp"



# Create directories

mkdir -p "$PORT/assets/level"
mkdir -p "$PORT/assets/model"
mkdir -p "$PORT/assets/sprite"
mkdir -p "$PORT/assets/boldfont"
mkdir -p "$PORT/assets/sprite"
mkdir -p "$PORT/assets/lang/jp/model"
mkdir -p "$PORT/assets/lang/jp/sprite"
mkdir -p "$PORT/assets/lang/pal/sprite"



# Copy and rename textures

